const s="http://localhost:5000";chrome.runtime.onMessage.addListener((t,o,e)=>{if(t.type==="LINK_CLICKED")return c(t.url,t.title).then(()=>e({ok:!0})).catch(()=>e({ok:!1})),!0});async function c(t,o){const e=await chrome.storage.local.get(["isTracking","token"]),a=e.isTracking,i=e.token;if(!a||!i)return;const n=await fetch(`${s}/api/links/extension`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${i}`},body:JSON.stringify({url:t,title:o})});if(!n.ok){const r=await n.json();console.warn("[Linker] Failed to save link:",r.message??n.statusText)}}
